
/**
 * Adds the -scrolled- class to the body if user scrolls
 */
jQuery(document).ready(function($){
  var siteHeader = $(".site-header");
  var theWindow = $(window);
  var theBody = $('body');
  theWindow.scroll(function() {
    var scroll = theWindow.scrollTop();

    if (scroll >= 100) {
      theBody.addClass("scrolled scrolled-100");
    } else {
      theBody.removeClass("scrolled");
      theBody.removeClass("scrolled-100");
      theBody.removeClass("scrolled-300");
    }

    if (scroll >= 500) {
      theBody.addClass("scrolled scrolled-500");
    } else {
      theBody.removeClass("scrolled-500");
    }
  });

});
;/*
 * Adds a checkbox with a label before each menu on the header and on each
 * sub-menu.
 *
 * You use this for adding drop down capabilities to the menus using CSS
 *
 * Author: Mario Yepes <marioy47@gmail.com>
 */
(function($) {

  $('.site-header .menu-item-has-children > a').each( function(i, obj) {

    // The menu or sub-menu as a jquery object
    var jquery_obj = $(obj);

    // Create the <label> as a jQuery object
    var label_toggle = $('<label />', {
      'for': 'menu-toggle-' + i,
      'class' : 'menu-toggle'
    });

    // Create the <checkbox> as a jQuery object
    var checkbox_toggle = $( '<input />', {
      'type': 'checkbox',
      'id': 'menu-toggle-' + i,
      'class' : 'menu-toggle',
      'checked': 'checked'
      } );

    // Add the checkbox and label to the dom
    jquery_obj.before(checkbox_toggle).before(label_toggle);
  });

  // The same but for menus
  $('.site-header ul.menu').each( function(i, obj) {

    // The menu or sub-menu as a jquery object
    var jquery_obj = $(obj);

    // Create the <label> as a jQuery object
    var label_toggle = $('<label />', {
      'for': 'top-menu-toggle-' + i,
      'class' : 'top-menu-toggle'
    });

    // Create the <checkbox> as a jQuery object
    var checkbox_toggle = $( '<input />', {
      'type': 'checkbox',
      'id': 'top-menu-toggle-' + i,
      'class' : 'top-menu-toggle',
      'checked': 'checked'
      } );

    // Add the checkbox and label to the dom
    jquery_obj.before(checkbox_toggle).before(label_toggle);
  });

})(jQuery);
;(function($) {

  var window_height = $(window).height();
  var header_height = $('.site-header').height();

  if (isNaN(parseInt(window_height))) window_height = 500;
  if (isNaN(parseInt(header_height))) header_height = 0;

  var css = ".window-height { min-height: " + (window_height - header_height) + "px;}" +
    " .half-window-height { min-height: " + (window_height - header_height)/2 + "px;}" ;

  var head = document.head || document.getElementsByTagName('head')[0];
  var style = document.createElement('style');

  style.type = 'text/css';
  if (style.styleSheet){
    style.styleSheet.cssText = css;
  } else {
    style.appendChild(document.createTextNode(css));
  }

  head.appendChild(style);

})(jQuery);
